import type { LabelHTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// Field's label on its own (console2.css forms): 12px in the soft grey, over or beside the control it names, never in
// place of one. `htmlFor` ties it to the control's id (Vue's `for`); `hint` adds a muted note after it, such as
// "optional".
export interface LabelProps extends LabelHTMLAttributes<HTMLLabelElement> {
  hint?: string
  children?: ReactNode
}

export function Label({ hint, className, children, ...rest }: LabelProps) {
  return <label data-ds="label" {...rest} className={cn('inline-flex items-baseline gap-1.5 type-meta text-fg-soft', className)}>{children}{hint && <span className="text-fg-muted">{hint}</span>}</label>
}

export default Label

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

